    def _discovery_tick(self):
        """Discover new sessions and remove dead ones.

        Flow: discover → register new → ghost dead → prune deleted CWDs →
        git status (all sessions) → refresh UI.
        """
        try:
            discovered = discover_sessions()
            alive_pids = set()

            # 1. Register new live sessions
            for session in discovered:
                if not validate_pid(pid=session.pid):
                    continue
                session.pid_alive = True
                alive_pids.add(session.pid)
                if session.pid not in self._sessions:
                    self._add_session(session)

            # 2. Convert dead sessions to ghosts (skip sandbox entries)
            dead_pids = set(self._sessions.keys()) - alive_pids
            for pid in dead_pids:
                entry = self._sessions.get(pid)
                if entry and not entry.unattached and not entry.sandbox:
                    cwd = entry.session.cwd
                    flagged = entry.flagged
                    last_active = entry.last_active
                    self._remove_session(pid)
                    self._create_ghost(cwd=cwd, flagged=flagged, last_active=last_active)

            # 2b. Discover and reconcile sandbox sessions
            sandbox_sessions = discover_sandbox_sessions()
            sandbox_ids = {s.session_id for s in sandbox_sessions}
            # Register new sandboxes and update phase for existing ones
            for sb_session in sandbox_sessions:
                if sb_session.session_id not in self._session_id_to_pid:
                    self._add_sandbox_session(sb_session)
                    logger.info("registered sandbox %s", sb_session.session_id)
                else:
                    pid = self._session_id_to_pid[sb_session.session_id]
                    entry = self._sessions.get(pid)
                    if entry and entry.sandbox_phase != sb_session.sandbox_phase:
                        entry.sandbox_phase = sb_session.sandbox_phase
                        entry.session.sandbox_phase = sb_session.sandbox_phase
            # Remove sandboxes that disappeared from openshell list.
            # Skip removal when discovery returns empty — likely a transient
            # openshell failure, not all sandboxes vanishing simultaneously.
            existing_sandbox_count = sum(1 for e in self._sessions.values() if e.sandbox)
            if sandbox_ids or existing_sandbox_count == 0:
                gone_pids = [
                    e.session.pid
                    for e in self._sessions.values()
                    if e.sandbox and e.session.session_id not in sandbox_ids
                ]
                for pid in gone_pids:
                    entry = self._sessions.get(pid)
                    if entry:
                        self._session_id_to_pid.pop(entry.session.session_id, None)
                        logger.info(
                            "sandbox %s removed (no longer in openshell)",
                            entry.session.session_id,
                        )
                    self._sessions.pop(pid, None)
            elif existing_sandbox_count > 0:
                logger.debug(
                    "skipping sandbox removal: openshell returned empty but %d sandboxes known",
                    existing_sandbox_count,
                )

            # 2c. Update sandbox VS Code connection state
            self._sandbox_vscode_tick_counter += 1
            sandbox_vscode_tick = (
                not self._first_tick_done
                or self._sandbox_vscode_tick_counter >= self._sandbox_vscode_tick_interval
            )
            if sandbox_vscode_tick:
                self._sandbox_vscode_tick_counter = 0
                self._update_sandbox_vscode_state()
                self._check_terminal_activity()

            # 3. On first tick, create unattached placeholders from state file
            if not self._first_tick_done:
                self._create_unattached_from_state(alive_pids)

            # 4. Prune ghosts whose CWD no longer exists
            stale_pids = [
                pid
                for pid, entry in self._sessions.items()
                if entry.unattached and not Path(entry.session.cwd).is_dir()
            ]
            for pid in stale_pids:
                cwd = self._sessions[pid].session.cwd
                self._sessions.pop(pid, None)
                logger.info("pruned ghost for deleted directory %s", cwd)

            # 5. Update git state for all sessions.
            # Live: git_check every tick, fetch every ~60s.
            # Ghosts: both every ~5 min.
            self._fetch_tick_counter += 1
            fetch_tick = self._fetch_tick_counter >= self._fetch_tick_interval
            if fetch_tick:
                self._fetch_tick_counter = 0
            self._ghost_git_tick_counter += 1
            ghost_tick = self._ghost_git_tick_counter >= self._ghost_git_tick_interval
            if ghost_tick:
                self._ghost_git_tick_counter = 0

            fetched_cwds: set[str] = set()
            for entry in self._sessions.values():
                is_ghost = entry.unattached
                if is_ghost and entry.sandbox and not sandbox_vscode_tick:
                    continue
                if is_ghost and not entry.sandbox and not ghost_tick:
                    continue

                cwd = entry.session.cwd

                # Fetch remote refs on the appropriate tick (deduplicated by CWD)
                should_fetch = ghost_tick if is_ghost else fetch_tick
                if (
                    should_fetch
                    and entry.git_status == config.GitStatus.PUSHED_NOT_MERGED
                    and cwd not in fetched_cwds
                ):
                    fetched_cwds.add(cwd)
                    if cwd not in self._trunk_cache:
                        self._populate_trunk_cache(cwd)
                    remote = self._trunk_cache[cwd].get("remote", "")
                    if remote:
                        try:
                            subprocess.run(
                                ["git", "fetch", remote],
                                cwd=cwd,
                                stdout=subprocess.DEVNULL,
                                stderr=subprocess.DEVNULL,
                                timeout=10,
                                creationflags=config.SUBPROCESS_FLAGS,
                            )
                        except (OSError, subprocess.TimeoutExpired):
                            pass

                # Update branch, git status, and merge status
                if entry.sandbox:
                    start = time.monotonic()
                    new_git_status, new_merged, new_branch = sandbox_git_check(sandbox_dir=cwd)
                    elapsed = time.monotonic() - start
                    if elapsed <= 2.0:
                        entry.git_status = new_git_status
                        entry.merged = new_merged
                        entry.branch = new_branch
                else:
                    trunk_branch = self._trunk_branch(cwd)
                    entry.branch = detect_branch(cwd=cwd, trunk_branch=trunk_branch)
                    trunk_ref = self._trunk_ref(cwd)
                    start = time.monotonic()
                    new_git_status, new_merged = git_check(
                        cwd=cwd, trunk_ref=trunk_ref, branch=entry.branch
                    )
                    elapsed = time.monotonic() - start
                    if elapsed <= 0.5:
                        entry.git_status = new_git_status
                        entry.merged = new_merged

            if fetched_cwds:
                # Clear trunk cache after fetch so newly-added remotes are detected
                self._trunk_cache.clear()

            # Poll Prometheus for session states from OTEL recording rules
            self._update_states_from_otel()

            # Refresh UI (state may not have changed, but rows may have been added/removed)
            self._refresh_ui()
            self._first_tick_done = True

        except Exception as exc:
            logger.error("discovery tick failed error=%s", exc)

        tick_ms = self._settings.poll_interval_seconds * 1000
        self._root.after(tick_ms, self._discovery_tick)

    # ------------------------------------------------------------------
    # Session lifecycle
    # ------------------------------------------------------------------

    def _populate_trunk_cache(self, cwd: str) -> None:
        """Populate trunk cache for a CWD using file reads (no subprocess)."""
        remote, trunk_ref, trunk_branch = read_trunk_info(cwd=cwd)
        self._trunk_cache[cwd] = {
            "branch": trunk_branch,
            "ref": trunk_ref,
            "remote": remote,
        }

    def _trunk_branch(self, cwd: str) -> str:
        """Return cached trunk branch name for a CWD, populating on first access."""
        if cwd not in self._trunk_cache:
            self._populate_trunk_cache(cwd)
        return self._trunk_cache[cwd].get("branch", "")

    def _trunk_ref(self, cwd: str) -> str:
        """Return cached trunk ref (e.g. 'origin/main') for a CWD."""
        if cwd not in self._trunk_cache:
            self._populate_trunk_cache(cwd)
        return self._trunk_cache[cwd].get("ref", "")

    def _is_ignored(self, cwd: str) -> bool:
        """Check if a CWD matches the ignore regex setting."""
        regex = self._settings.ignore_regex
        if not regex:
            return False
        try:
            return bool(re.match(regex, cwd))
        except re.error:
            return False

    def _add_session(self, session: SessionInfo):
        if self._is_ignored(session.cwd):
            logger.debug("pid=%d ignored (cwd=%s matches ignore_regex)", session.pid, session.cwd)
            return
        entry = _SessionEntry(session)
        entry.last_active = _now_epoch()
        # All new sessions start as IDLE until a hook event updates them.
        entry.container = detect_container(session.pid)
        entry.container = find_window_for_session(session.cwd, entry.container)
        trunk_branch = self._trunk_branch(session.cwd)
        entry.branch = detect_branch(cwd=session.cwd, trunk_branch=trunk_branch)
        trunk_ref = self._trunk_ref(session.cwd)
        start = time.monotonic()
        entry.git_status, entry.merged = git_check(
            cwd=session.cwd, trunk_ref=trunk_ref, branch=entry.branch
        )
        elapsed = time.monotonic() - start
        if elapsed > 0.5:
            logger.warning(
                "pid=%d git check took %.1fs on first detection",
                session.pid,
                elapsed,
            )

        # Replace unattached placeholder if one exists for this CWD
        unattached_pid = self._find_unattached_pid(session.cwd)
        if unattached_pid is not None:
            old = self._sessions.pop(unattached_pid, None)
            if old:
                entry.flagged = old.flagged
                # Live session replaces ghost — always unhide so it's visible
                entry.hidden = False
                logger.debug(
                    "pid=%d replaced unattached placeholder for %s", session.pid, session.cwd
                )
        else:
            self._apply_saved_state(entry)

        self._sessions[session.pid] = entry
        self._session_id_to_pid[session.session_id] = session.pid

        cwd_short = cwd_basename(cwd=session.cwd)
        logger.debug(
            "pid=%d project=%s new_state=%s prior_state=None",
            session.pid,
            cwd_short,
            entry.state.value,
        )

    def _add_sandbox_session(self, session: SessionInfo):
        """Register a sandbox session (no host PID, no container detection)."""
        if self._is_ignored(session.cwd):
            logger.debug("sandbox ignored (cwd=%s matches ignore_regex)", session.cwd)
            return
        self._next_synthetic_pid -= 1
        synthetic_pid = self._next_synthetic_pid
        session = SessionInfo(
            pid=synthetic_pid,
            session_id=session.session_id,
            cwd=session.cwd,
            started_at=session.started_at,
            entrypoint=session.entrypoint,
            sandbox_phase=session.sandbox_phase,
        )
        entry = _SessionEntry(session)
        entry.sandbox = True
        entry.sandbox_phase = session.sandbox_phase
        entry.unattached = True
        entry.last_active = _now_epoch()
        entry.container = ContainerInfo(container_type=ContainerType.SANDBOX)
        entry.git_status, entry.merged, entry.branch = sandbox_git_check(sandbox_dir=session.cwd)

        # Replace unattached placeholder if one exists for this CWD
        unattached_pid = self._find_unattached_pid(session.cwd)
        if unattached_pid is not None:
            old = self._sessions.pop(unattached_pid, None)
            if old:
                entry.flagged = old.flagged
                entry.hidden = False
        else:
            self._apply_saved_state(entry)

        self._sessions[synthetic_pid] = entry
        self._session_id_to_pid[session.session_id] = synthetic_pid
        logger.debug(
            "sandbox session project=%s pid=%d",
            cwd_basename(cwd=session.cwd),
            synthetic_pid,
        )

    def _update_sandbox_vscode_state(self):
        """Check which sandboxes have VS Code connected and update unattached state."""
        sandbox_entries = [e for e in self._sessions.values() if e.sandbox]
        if not sandbox_entries:
            return

        if config.IS_LINUX:
            from claude_dashboard.platform.linux import _list_windows_dbus

            windows = _list_windows_dbus()
        else:
            windows = []

        if not windows:
            logger.debug("sandbox vscode check: 0 windows from D-Bus")

        vscode_titles = set()
        for w in windows:
            wm_class = (w.get("wm_class") or "").lower()
            if "code" in wm_class or "cursor" in wm_class:
                vscode_titles.add((w.get("title") or "").lower())

        for entry in sandbox_entries:
            folder_name = Path(entry.session.cwd).name.lower()
            has_vscode = any(folder_name in title for title in vscode_titles)
            if entry.unattached == has_vscode:
                was_connected = not entry.unattached
                entry.unattached = not has_vscode
                if was_connected and entry.unattached and entry.state == StatusState.READY:
                    entry.state = StatusState.IDLE
                logger.debug(
                    "sandbox %s vscode_connected=%s",
                    folder_name,
                    has_vscode,
                )

    def _check_terminal_activity(self):
        """Detect non-Claude processes in VS Code terminals matching session CWDs."""
        if not config.IS_LINUX:
            return

        from claude_dashboard.platform.linux import _list_windows_dbus

        windows = _list_windows_dbus()
        vscode_pids = {
            w["pid"]
            for w in windows
            if (w.get("wm_class") or "").lower() in ("code", "cursor") and w.get("pid")
        }
        if not vscode_pids:
            return

        session_cwds = [e.session.cwd for e in self._sessions.values()]
        if not session_cwds:
            return

        active_cwds: set[str] = set()
        for vscode_pid in vscode_pids:
            active_cwds |= detect_terminal_activity(
                session_cwds=session_cwds, vscode_pid=vscode_pid
            )

        for entry in self._sessions.values():
            new_val = entry.session.cwd in active_cwds
            if entry.has_terminal_activity != new_val:
                entry.has_terminal_activity = new_val
                logger.debug(
                    "terminal_activity=%s cwd=%s",
                    new_val,
                    cwd_basename(cwd=entry.session.cwd),
                )

    def _find_unattached_pid(self, cwd: str) -> int | None:
        """Find an unattached placeholder PID for the given CWD."""
        for pid, entry in self._sessions.items():
            if entry.unattached and entry.session.cwd == cwd:
                return pid
        return None

    def _create_unattached_from_state(self, alive_pids: set[int]):
        """Create ghost entries from state file for CWDs without live sessions."""
        live_cwds = {e.session.cwd for e in self._sessions.values()}
        for cwd, saved in self._saved_state.items():
            if cwd in live_cwds:
                continue
            if self._is_ignored(cwd):
                continue
            self._next_synthetic_pid -= 1
            synthetic_pid = self._next_synthetic_pid
            session = SessionInfo(
                pid=synthetic_pid,
                session_id=f"unattached-{synthetic_pid}",
                cwd=cwd,
                started_at=0,
                pid_alive=False,
            )
            entry = _SessionEntry(session)
            entry.unattached = True
            if saved.get("flagged"):
                entry.flagged = True
            if saved.get("hidden"):
                entry.hidden = True
            last_active = saved.get("last_active")
            if isinstance(last_active, (int, float)):
                entry.last_active = float(last_active)
            entry.branch = detect_branch(cwd=cwd, trunk_branch=self._trunk_branch(cwd))
            trunk_ref = self._trunk_ref(cwd)
            entry.git_status, entry.merged = git_check(
                cwd=cwd, trunk_ref=trunk_ref, branch=entry.branch
            )
            self._sessions[synthetic_pid] = entry
            logger.debug("created unattached placeholder for %s pid=%d", cwd, synthetic_pid)
        self._evict_oldest_ghosts()

    def _create_ghost(self, *, cwd: str, flagged: bool = False, last_active: float = 0.0):
        """Create an unattached ghost for a CWD if no live session or ghost exists for it."""
        # Skip if another live session still uses this CWD
        for entry in self._sessions.values():
            if entry.session.cwd == cwd:
                logger.debug("skip ghost for %s — session still exists", cwd)
                return
        self._next_synthetic_pid -= 1
        synthetic_pid = self._next_synthetic_pid
        session = SessionInfo(
            pid=synthetic_pid,
            session_id=f"unattached-{synthetic_pid}",
            cwd=cwd,
            started_at=0,
            pid_alive=False,
        )
        entry = _SessionEntry(session)
        entry.unattached = True
        entry.flagged = flagged
        entry.last_active = last_active or _now_epoch()
        entry.branch = detect_branch(cwd=cwd, trunk_branch=self._trunk_branch(cwd))
        trunk_ref = self._trunk_ref(cwd)
        entry.git_status, entry.merged = git_check(
            cwd=cwd, trunk_ref=trunk_ref, branch=entry.branch
        )
        self._sessions[synthetic_pid] = entry
        logger.info("created ghost for %s pid=%d", cwd, synthetic_pid)
        self._evict_oldest_ghosts()

    def _evict_oldest_ghosts(self):
        """Remove oldest non-flagged ghosts to keep total sessions at max_sessions."""
        max_sessions = self._settings.max_sessions
        total = len(self._sessions)
        if total <= max_sessions:
            return
        candidates = [
            (pid, entry)
            for pid, entry in self._sessions.items()
            if entry.unattached and not entry.flagged
        ]
        if not candidates:
            return
        candidates.sort(key=lambda pair: pair[1].last_active)
        evict_count = min(len(candidates), total - max_sessions)
        for pid, entry in candidates[:evict_count]:
            logger.info(
                "evicting ghost pid=%d cwd=%s last_active=%s",
                pid,
                entry.session.cwd,
                entry.last_active,
            )
            self._sessions.pop(pid, None)
        self._save_session_state()

    def _remove_session(self, pid: int):
        entry = self._sessions.pop(pid, None)
        if entry:
            self._session_id_to_pid.pop(entry.session.session_id, None)
            logger.debug("session gone pid=%d", pid)

    # ------------------------------------------------------------------
    # OTEL state polling (replaces hook server)
    # ------------------------------------------------------------------

    def _update_states_from_otel(self):
        """Poll Prometheus for session state metrics and update entries."""
        url = config.resolve_prometheus_url(settings_url=self._settings.prometheus_url)
        states = poll_session_states(prometheus_url=url)
        changed = False
        for session_id, session_state in states.items():
            pid = self._session_id_to_pid.get(session_id)
            if pid is None:
                pid = self._match_sandbox_by_hostname(session_state.host_name)
            if pid is None:
                continue
            entry = self._sessions.get(pid)
            if entry is None:
                continue
            new_state = session_state.state
            prior = entry.state
            if new_state == prior:
                continue
            # Skip if OTEL reports the same state user manually cleared.
            # Accepts any different state (genuinely new activity).
            if entry.state_cleared_from and new_state.value == entry.state_cleared_from:
                continue
            entry.state = new_state
            entry.state_cleared_from = ""
            entry.last_active = _now_epoch()
            changed = True
            cwd_short = cwd_basename(cwd=entry.session.cwd)
            logger.debug(
                "pid=%d project=%s new_state=%s prior_state=%s source=otel",
                pid,
                cwd_short,
                new_state.value,
                prior.value,
            )
        # Stale WORKING → READY: sessions not in current OTEL results that
        # are WORKING transition to READY ("just finished, needs attention").
        # PERMISSION_REQUIRED and AWAITING_INPUT are left alone — stale metric
        # doesn't mean the user answered; those persist until explicitly cleared.
        otel_session_ids = set(states.keys())
        for entry in self._sessions.values():
            if entry.session.pid_alive:
                continue
            if entry.state != StatusState.WORKING:
                continue
            sid = entry.session.session_id
            if sid in otel_session_ids:
                continue
            entry.state = StatusState.READY
            changed = True

        if changed:
            self._refresh_ui()

    def _match_sandbox_by_hostname(self, host_name: str) -> int | None:
        """Match a Prometheus host_name label to a sandbox session PID."""
        if not host_name.startswith("sandbox-"):
            return None
        sandbox_id = f"sandbox-{host_name[len('sandbox-'):]}"
        return self._session_id_to_pid.get(sandbox_id)

    # ------------------------------------------------------------------
    # UI refresh
    # ------------------------------------------------------------------

    def _sorted_entries(self) -> list["_SessionEntry"]:
        """Return all session entries sorted by display name."""
        return sorted(
            self._sessions.values(),
            key=lambda e: cwd_relative_to_home(cwd=e.session.cwd).lower(),
        )

    def _refresh_ui(self):
        """Debounced UI refresh. High-priority states bypass debounce (FR-043)."""
        all_entries = self._sorted_entries()
        bypass = any(
            entry.state in (StatusState.PERMISSION_REQUIRED, StatusState.AWAITING_INPUT)
            for entry in all_entries
            if not entry.hidden
        )

        if bypass:
            if self._debounce_id is not None:
                self._root.after_cancel(self._debounce_id)
                self._debounce_id = None
            logger.debug("refresh_ui: bypass (immediate)")
            self._do_refresh_ui(all_entries)
        else:
            had_pending = self._debounce_id is not None
            if had_pending:
                self._root.after_cancel(self._debounce_id)
            self._debounce_id = self._root.after(
                _DEBOUNCE_MS,
                self._do_refresh_ui_deferred,
            )
            logger.debug(
                "refresh_ui: debounce %dms (cancelled_pending=%s)",
                _DEBOUNCE_MS,
                had_pending,
            )

    def _do_refresh_ui_deferred(self):
        """Called by debounce timer — re-reads current state to avoid staleness."""
        self._debounce_id = None
        self._do_refresh_ui(self._sorted_entries())

    def _do_refresh_ui(self, all_entries: list["_SessionEntry"]):
        """Actual UI refresh logic."""
        for entry in all_entries:
            if not entry.hidden:
                logger.debug(
                    "ROW cwd=%s sandbox=%s unattached=%s state=%s pid=%d",
                    cwd_basename(cwd=entry.session.cwd),
                    entry.sandbox,
                    entry.unattached,
                    entry.state.value,
                    entry.session.pid,
                )
        visible_states = [
            SessionRow(
                session=entry.session,
                state=entry.state,
                container=entry.container,
                branch=entry.branch,
                flagged=entry.flagged,
                git_status=entry.git_status,
                merged=entry.merged,
                agent_count=0,
                unattached=entry.unattached if not entry.sandbox else False,
                sandbox_phase=entry.sandbox_phase if entry.sandbox else "",
                sandbox_connected=entry.sandbox and not entry.unattached,
                has_terminal_activity=entry.has_terminal_activity,
            )
            for entry in all_entries
            if not entry.hidden
        ]
        self._main_window.update_sessions(visible_states)

        highest = self._highest_priority_state(visible_states)
        if highest != self._tray_state:
            self._tray_state = highest
            update_tray_icon(self._tray_icon, color=self._tray_color_for_state(highest))

        active = sum(1 for e in all_entries if not e.hidden and not e.unattached)
        hidden_live = sum(1 for e in all_entries if e.hidden and not e.unattached)
        hidden_ghost = sum(1 for e in all_entries if e.hidden and e.unattached)
        highest_git = self._highest_title_git_status(visible_states)
        self._main_window.update_title_bar(
            active=active,
            hidden_live=hidden_live,
            hidden_ghost=hidden_ghost,
            highest_state_color=self._tray_color_hex_for_state(highest),
            highest_git_status=highest_git,
        )

        self._save_session_state()

    # ------------------------------------------------------------------
    # Row click
    # ------------------------------------------------------------------

    def _on_row_left_click(self, session: SessionInfo):
        logger.info("row clicked pid=%d cwd=%s", session.pid, session.cwd)
        entry = self._sessions.get(session.pid)

        # Clicking a Ready session clears to Idle
        if entry and entry.state == StatusState.READY:
            entry.state_cleared_from = entry.state.value
            entry.state = StatusState.IDLE
            logger.debug("pid=%d clicked, cleared ready to idle", session.pid)
            self._refresh_ui()

        # Sandbox sessions open in VS Code without touching tasks.json
        if entry and entry.sandbox:
            self._launch_vscode(folder=session.cwd)
            return

        # Unattached sessions open in VS Code
        if entry and entry.unattached:
            self._launch_vscode(folder=session.cwd)
            return

        container = entry.container if entry else None

        if not container:
            container = detect_container(session.pid)
            container = find_window_for_session(session.cwd, container)
            if entry:
                entry.container = container

        has_handle = bool(container and (container.window_handle or container.process_pid))
        # Even with no detected container, Windows can fall back to `code <cwd>`
        # when the session is hosted outside VS Code's integrated terminal.
        if has_handle or (config.IS_WINDOWS and session.cwd):
            target = container if container else ContainerInfo()
            logger.info(
                "row click pid=%d container_type=%s has_handle=%s",
                session.pid,
                target.container_type.value,
                has_handle,
            )
            success = foreground_window(target, cwd=session.cwd)
            if not success:
                logger.warning("failed to foreground pid=%d", session.pid)
            if config.IS_WINDOWS:
                self._root.after(500, self._log_post_click_foreground, session.pid)
                self._root.after(1500, self._log_post_click_foreground, session.pid)

    def _log_post_click_foreground(self, pid: int) -> None:
        """Diagnostic: log which window is foreground after a click."""
        if not config.IS_WINDOWS:
            return
        try:
            from claude_dashboard.platform.windows import log_foreground_state

            log_foreground_state(f"post-click pid={pid}")
        except Exception as exc:  # pragma: no cover - defensive
            logger.debug("post-click foreground check failed: %s", exc)

    def _on_row_double_click(self, session: SessionInfo):
        """Double-click toggles between Idle and Ready."""
        entry = self._sessions.get(session.pid)
        if not entry:
            return
        if entry.state == StatusState.IDLE:
            entry.state = StatusState.READY
            logger.debug("pid=%d double-clicked, idle to ready", session.pid)
        else:
            entry.state_cleared_from = entry.state.value
            entry.state = StatusState.IDLE
            logger.debug("pid=%d double-clicked, state cleared to idle", session.pid)
        self._refresh_ui()

    def _on_row_middle_click(self, session: SessionInfo):
        """Middle-click toggles flagged state."""
        entry = self._sessions.get(session.pid)
        if entry:
            entry.flagged = not entry.flagged
            logger.debug("pid=%d flagged=%s", session.pid, entry.flagged)
            self._refresh_ui()

    def _on_row_right_click(self, session: SessionInfo, x: int, y: int):
        """Per-row right-click: sandbox/ghost/live get distinct menus."""
        entry = self._sessions.get(session.pid)
        if entry and entry.sandbox:
            self._show_sandbox_context_menu(session, x, y)
        elif entry and entry.unattached:
            self._show_ghost_context_menu(session, x, y)
        else:
            self._show_live_context_menu(session, x, y)

    def _show_live_context_menu(self, session: SessionInfo, x: int, y: int):
        """Live session menu: Hide, Clear State."""
        if self._context_menu_open:
            self._context_menu.unpost()
            self._context_menu_open = False
            return
        self._context_menu.unpost()
        self._context_menu.delete(0, tk.END)

        entry = self._sessions.get(session.pid)
        if not entry:
            return

        cwd_display = cwd_relative_to_home(cwd=session.cwd)

        def hide():
            entry.hidden = True
            logger.info("pid=%d hidden via context menu", session.pid)
            self._save_session_state()
            self._refresh_ui()

        def clear_state():
            entry.state_cleared_from = entry.state.value
            entry.state = StatusState.IDLE
            logger.info("pid=%d state cleared via context menu", session.pid)
            self._refresh_ui()

        self._context_menu.add_command(label=cwd_display, state=tk.DISABLED)
        self._context_menu.add_separator()
        self._context_menu.add_command(label="Hide", command=hide)
        self._context_menu.add_command(label="Clear State", command=clear_state)

        self._context_menu_open = True
        popup_menu_clamped(self._context_menu, x=x, y=y)

    def _show_sandbox_context_menu(self, session: SessionInfo, x: int, y: int):
        """Live sandbox menu: Hide, Clear State."""
        if self._context_menu_open:
            self._context_menu.unpost()
            self._context_menu_open = False
            return
        self._context_menu.unpost()
        self._context_menu.delete(0, tk.END)

        cwd_display = cwd_relative_to_home(cwd=session.cwd)
        entry = self._sessions.get(session.pid)

        def hide():
            if entry:
                entry.hidden = True
                logger.info("sandbox %s hidden via context menu", cwd_display)
                self._save_session_state()
                self._refresh_ui()

        def clear_state():
            if entry:
                entry.state_cleared_from = entry.state.value
                entry.state = StatusState.IDLE
                logger.info("sandbox %s state cleared via context menu", cwd_display)
                self._refresh_ui()

        sandbox_name = session.session_id.removeprefix("sandbox-")

        def delete_sandbox():
            self._sessions.pop(session.pid, None)
            self._session_id_to_pid.pop(session.session_id, None)
            logger.info("sandbox %s delete requested", sandbox_name)
            self._refresh_ui()
            threading.Thread(
                target=self._run_sandbox_delete,
                args=(sandbox_name,),
                daemon=True,
            ).start()

        self._context_menu.add_command(label=f"Sandbox: {cwd_display}", state=tk.DISABLED)
        self._context_menu.add_separator()
        self._context_menu.add_command(label="Hide", command=hide)
        self._context_menu.add_command(label="Clear State", command=clear_state)
        self._context_menu.add_command(label="Delete Sandbox", command=delete_sandbox)

        self._context_menu_open = True
        popup_menu_clamped(self._context_menu, x=x, y=y)

    def _show_ghost_context_menu(self, session: SessionInfo, x: int, y: int):
        """Ghost (local) menu: Hide, Dismiss."""
        if self._context_menu_open:
            self._context_menu.unpost()
            self._context_menu_open = False
            return
        self._context_menu.unpost()
        self._context_menu.delete(0, tk.END)

        cwd_display = cwd_relative_to_home(cwd=session.cwd)

        def dismiss():
            self._sessions.pop(session.pid, None)
            logger.info("pid=%d ghost dismissed via context menu", session.pid)
            self._refresh_ui()

        def hide():
            entry = self._sessions.get(session.pid)
            if entry:
                entry.hidden = True
                logger.info("pid=%d ghost hidden via context menu", session.pid)
                self._save_session_state()
                self._refresh_ui()

        self._context_menu.add_command(label=f"Ghost: {cwd_display}", state=tk.DISABLED)
        self._context_menu.add_separator()
        self._context_menu.add_command(label="Hide", command=hide)
        self._context_menu.add_command(label="Dismiss", command=dismiss)

        self._context_menu_open = True
        popup_menu_clamped(self._context_menu, x=x, y=y)

    def _run_sandbox_delete(self, sandbox_name: str):
        """Run sandbox.sh --delete <name> in a background thread."""
        sandbox_sh = shutil.which("sandbox.sh")
        if not sandbox_sh:
            logger.warning("sandbox.sh not found on PATH, cannot delete %s", sandbox_name)
            return
        try:
            subprocess.run(
                [sandbox_sh, "--delete", sandbox_name],
                capture_output=True,
                timeout=30,
                creationflags=config.SUBPROCESS_FLAGS,
            )
            logger.info("sandbox delete completed name=%s", sandbox_name)
        except (OSError, subprocess.TimeoutExpired) as exc:
            logger.warning("sandbox delete failed name=%s error=%s", sandbox_name, exc)

    def _launch_vscode(self, *, folder: str):
        """Launch VS Code for the given folder."""
        code_path = shutil.which("code")
        if not code_path:
            logger.warning(
                "VS Code 'code' command not found — install it via "
                "Command Palette > Shell Command: Install 'code' command in PATH"
            )
            return
        try:
            subprocess.Popen(
                [code_path, folder],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=config.SUBPROCESS_FLAGS,
            )
            logger.info("launched VS Code for folder=%s", folder)
        except OSError as exc:
            logger.warning("failed to launch VS Code for folder=%s error=%s", folder, exc)

    def _open_folder(self):
        """Show a folder picker and open the selected folder in VS Code."""
        folder = filedialog.askdirectory(title="Open folder in VS Code")
        if not folder:
            return
        self._launch_vscode(folder=folder)

    @staticmethod
    def _is_error_sandbox(entry: "_SessionEntry") -> bool:
        return entry.sandbox and entry.sandbox_phase == "Error"

    def _on_ghost_toggle(self, *, force_show: bool = False):
        """Middle-click on title bar — toggle ghost session visibility.

        If force_show is True, always show ghosts (used when unshading).
        Otherwise: if any non-flagged ghosts are visible, hide them.
        Flagged ghosts are never hidden by this toggle.
        """

        def _is_toggleable(entry: _SessionEntry) -> bool:
            if not entry.unattached:
                return False
            if entry.flagged:
                return False
            if self._is_error_sandbox(entry):
                return False
            return True

        if force_show:
            hide = False
        else:
            any_visible = any(_is_toggleable(e) and not e.hidden for e in self._sessions.values())
            hide = any_visible
        for entry in self._sessions.values():
            if _is_toggleable(entry):
                entry.hidden = hide
        self._ghosts_hidden = hide
        logger.info("ghosts %s via title bar", "hidden" if hide else "shown")
        self._save_session_state()
        self._refresh_ui()

    # ------------------------------------------------------------------
    # Session visibility menu
    # ------------------------------------------------------------------

    def _build_sessions_menu(self, menu: tk.Menu):
        """Populate a menu with session visibility checkboxes (live sessions only)."""
        self._session_vars.clear()
        all_entries = self._sorted_entries()
        for entry in all_entries:
            if entry.unattached and not entry.sandbox:
                continue
            var = tk.BooleanVar(value=not entry.hidden)
            self._session_vars.append(var)
            display_name = cwd_relative_to_home(cwd=entry.session.cwd)

            def make_toggle(e=entry, v=var):
                def toggle():
                    e.hidden = not v.get()
                    self._save_session_state()
                    self._refresh_ui()

                return toggle

            menu.add_checkbutton(
                label=display_name,
                variable=var,
                command=make_toggle(),
            )

    def _on_right_click(self, x: int, y: int):
        """Window-level right-click on empty areas — show sessions visibility menu."""
        if self._context_menu_open:
            self._context_menu.unpost()
            self._context_menu_open = False
            return
        self._context_menu.unpost()
        self._context_menu.delete(0, tk.END)

        self._build_sessions_menu(self._context_menu)

        self._context_menu_open = True
        popup_menu_clamped(self._context_menu, x=x, y=y)

    # ------------------------------------------------------------------
    # Session state persistence (restart continuity)
    # ------------------------------------------------------------------

    def _load_session_state(self) -> dict[str, dict]:
        """Load saved session state keyed by CWD."""
        try:
            data = json.loads(config.STATE_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return data
        except (FileNotFoundError, json.JSONDecodeError, OSError):
            pass
        return {}

    def _save_session_state(self):
        """Snapshot mutable session state to disk."""
        state: dict[str, dict] = {}
        for entry in self._sessions.values():
            cwd = entry.session.cwd
            if self._is_ignored(cwd):
                continue
            if cwd in state:
                if not entry.hidden:
                    state[cwd]["hidden"] = False
                if entry.last_active > state[cwd].get("last_active", 0.0):
                    state[cwd]["last_active"] = entry.last_active
            else:
                state[cwd] = {
                    "state": entry.state.value,
                    "hidden": entry.hidden,
                    "flagged": entry.flagged,
                    "last_active": entry.last_active,
                    "state_cleared_from": entry.state_cleared_from,
                }

        try:
            atomic_write_json(data=state, path=config.STATE_FILE)
        except OSError as exc:
            logger.debug("failed to save session state error=%s", exc)

    def _apply_saved_state(self, entry: "_SessionEntry"):
        """Apply saved state from a previous run to a newly discovered session."""
        saved = self._saved_state.get(entry.session.cwd)
        if not saved:
            return
        if saved.get("flagged"):
            entry.flagged = True
        if saved.get("hidden"):
            entry.hidden = True
        last_active = saved.get("last_active")
        if isinstance(last_active, (int, float)):
            entry.last_active = float(last_active)
        state_cleared_from = saved.get("state_cleared_from")
        if isinstance(state_cleared_from, str) and state_cleared_from:
            entry.state_cleared_from = state_cleared_from
        state_val = saved.get("state")
        if state_val:
            try:
                entry.state = StatusState(state_val)
            except ValueError:
                pass

    # ------------------------------------------------------------------
    # Window management
    # ------------------------------------------------------------------

    def _toggle_window(self):
        viewable = self._main_window.toplevel.winfo_viewable()
        logger.debug(
            "toggle_window viewable=%s x=%s y=%s h=%s",
            viewable,
            self._main_window.toplevel.winfo_x(),
            self._main_window.toplevel.winfo_y(),
            self._main_window.toplevel.winfo_height(),
        )
        if viewable:
            self._main_window.hide()
        else:
            self._main_window.show()

    def _show_window(self):
        self._main_window.show()

    def _hide_window(self):
        self._main_window.hide()

    def _open_settings(self):
        SettingsWindow(self._root, self._settings, on_save=self._on_settings_save)

    def _on_settings_save(self, new_settings: Settings):
        self._settings = new_settings
        self._save_settings_safe()
        set_run_on_startup(enabled=new_settings.run_on_startup)
        # Remove sessions that now match the ignore regex
        if new_settings.ignore_regex:
            ignored_pids = [
                pid for pid, entry in self._sessions.items() if self._is_ignored(entry.session.cwd)
            ]
            for pid in ignored_pids:
                self._sessions.pop(pid, None)
            if ignored_pids:
                self._save_session_state()
        self._main_window.apply_settings(new_settings)
        self._refresh_ui()
        logger.info("settings saved and applied")

    def _restart(self):
        """Save state, tear down, and re-exec the same process."""
        self._save_window_position()
        self._save_settings_safe()
        self._save_session_state()
        if self._tray_icon:
            self._tray_icon.stop()
        self._root.quit()
        logger.info("restarting dashboard")
        args = build_restart_args()
        try:
            os.execv(sys.executable, args)
        except OSError:
            logger.exception("failed to restart via execv")

    def _quit(self):
        self._save_window_position()
        self._save_settings_safe()
        if self._tray_icon:
            self._tray_icon.stop()
        self._root.quit()

    def _on_position_save(self, x: int, y: int):
        self._settings.window_x = x
        self._settings.window_y = y
        self._save_settings_safe()

    def _on_width_save(self, width: int):
        self._settings.row_width = width
        self._save_settings_safe()

    def _save_settings_safe(self):
        try:
            save_settings(self._settings)
        except OSError as exc:
            logger.error("failed to save settings: %s", exc)

    def _save_window_position(self):
        x, y = self._main_window.get_position()
        if x is not None and y is not None:
            self._settings.window_x = x
            self._settings.window_y = y

    # ------------------------------------------------------------------
    # Tray priority
    # ------------------------------------------------------------------

    def _highest_priority_state(
        self,
        session_states: list[SessionRow],
    ) -> StatusState | None:
        """Pick the highest-priority actionable state for the tray icon.

        Non-actionable states (e.g. Working) are skipped — the tray icon
        should only reflect states where the user can take action.
        """
        if not session_states:
            return None
        best = None
        best_priority = 999
        for row in session_states:
            if row.unattached:
                continue
            state = row.state
            if state not in _ACTIONABLE_STATES:
                continue
            p = _STATE_PRIORITY.get(state, 999)
            if p < best_priority:
                best = state
                best_priority = p
        return best

    @staticmethod
    def _highest_title_git_status(
        session_states: list[SessionRow],
    ) -> GitStatus | None:
        """Pick the highest-priority git status across visible rows for the title bar."""
        best = None
        best_priority = 999
        for row in session_states:
            gs = row.git_status
            if gs is None or gs == GitStatus.CLEAN:
                continue
            p = _TITLE_GIT_PRIORITY.get(gs, 999)
            if p < best_priority:
                best = gs
                best_priority = p
        return best

    def _tray_color_for_state(self, state: StatusState | None) -> tuple[int, int, int]:
        hex_color = self._tray_color_hex_for_state(state)
        return config.hex_to_rgb(hex_color=hex_color)

    def _tray_color_hex_for_state(self, state: StatusState | None) -> str:
        color_map = {
            StatusState.PERMISSION_REQUIRED: self._settings.color_permission_required,
            StatusState.AWAITING_INPUT: self._settings.color_awaiting_input,
            StatusState.READY: self._settings.color_ready,
            StatusState.WORKING: self._settings.color_working,
            StatusState.IDLE: self._settings.color_idle,
        }
        return (
            color_map.get(state, self._settings.color_idle) if state else self._settings.color_idle
        )
